    Coordinate offset = helper.getOffset(sourceDir);
    Coordinate sourceCoord = getSourceCell().getCoord();
    Coordinate startCoord = sourceCoord.add(offset);
    
    int sr = startCoord.getRow();
    int sc = startCoord.getCol();
    
    if (sr < 0 || sr >= getRows() || sc < 0 || sc >= getCols()) {
      return false;
    }
    
    // BFS
    boolean[][] visited = new boolean[getRows()][getCols()];
    Queue<Coordinate> queue = new LinkedList<Coordinate>();
    
    // Check if the starting cell is the sink
    Cell startCell = getCell()[sr][sc];
    if (startCell == getSinkCell()) {
      return true;
    }
    
    // Check if starting cell is a fillable cell with a pipe
    if (!(startCell instanceof FillableCell)) {
      return false;
    }
    
    FillableCell startFillable = (FillableCell) startCell;
    if (startFillable.getPipe() == null) {
      return false;
    }
    
    // Check that the source direction connects to the pipe in the starting cell
    Direction opposite = helper.getOpposite(sourceDir);
    boolean sourceConnects = false;
    for (Direction conn : startFillable.getPipe().getConnections()) {
      if (conn == opposite) {
        sourceConnects = true;
        break;
      }
    }
    if (!sourceConnects) {
      return false;
    }
    
    visited[sr][sc] = true;
    queue.add(startCoord);
    
    while (!queue.isEmpty()) {
      Coordinate current = queue.poll();
      Cell currentCell = getCell()[current.getRow()][current.getCol()];
      
      EList<Direction> connections = null;
      
      if (currentCell instanceof FillableCell) {
        FillableCell fc = (FillableCell) currentCell;
        if (fc.getPipe() == null) {
          continue;
        }
        connections = fc.getPipe().getConnections();
      } else {
        continue;
      }
      
      for (Direction dir : connections) {
        Coordinate off = helper.getOffset(dir);
        Coordinate nextCoord = current.add(off);
        int nr = nextCoord.getRow();
        int nc = nextCoord.getCol();
        
        if (nr < 0 || nr >= getRows() || nc < 0 || nc >= getCols()) {
          continue;
        }
        
        if (visited[nr][nc]) {
          continue;
        }
        
        Cell neighborCell = getCell()[nr][nc];
        
        // Check if we reached the sink
        if (neighborCell == getSinkCell()) {
          return true;
        }
        
        // Check if neighbor connects back
        Direction opp = helper.getOpposite(dir);
        boolean neighborConnects = false;
        
        if (neighborCell instanceof FillableCell) {
          FillableCell fc = (FillableCell) neighborCell;
          if (fc.getPipe() != null) {
            for (Direction conn : fc.getPipe().getConnections()) {
              if (conn == opp) {
                neighborConnects = true;
                break;
              }
            }
          }
        }
        
        if (neighborConnects) {
          visited[nr][nc] = true;
          queue.add(nextCoord);
        }
      }
    }
    
