  public boolean hasLost()
  {
    // The player loses when a water-flow update fills no new pipes.
    // Compare the current number of filled tiles with the previous number.
    int currentFilledCount = getFilledTiles().size();
    int prevFilled = getPrevFilledTiles();
    
    // If no new tiles were filled compared to the previous count, the player has lost.
    // But only if the prevFilledDistance is not null (meaning water has actually started advancing)
    if (getPrevFilledDistance() != null && currentFilledCount == prevFilled) {
      return true;
    }
    
    return false;
  }

